#[derive(Clone, Copy, PartialEq, Eq)]
enum Region {
    A, // x > y
    B, // y > x
}

fn solve(_n: i8, s: Vec<char>) -> i8 {
    // Use a signed wider type to avoid i8 overflow on updates.
    let mut d: i16 = 0; // d = x - y
    let mut last_region: Option<Region> = None;
    let mut transitions: i16 = 0;

    for ch in s {
        match ch {
            'R' => d += 1,
            'U' => d -= 1,
            _ => unreachable!("Input guarantees only 'U' or 'R'"),
        }

        if d == 0 {
            // On the border; do not update last_region.
            continue;
        }

        let current = if d > 0 { Region::A } else { Region::B };

        if let Some(prev) = last_region {
            if prev != current {
                transitions += 1;
            }
        }
        // First ever entry into a region sets last_region but does not count.
        last_region = Some(current);
    }

    transitions as i8
}